const $=id=>document.getElementById(id),app=$('app'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),now=()=>D.serverTimestamp(),cp=()=>`sparkCourses/${courseId}`,ep=()=>`${cp()}/exams/${examId}`;
function demoAllowed(){if(!user||profile?.role==='student')return false;if(isAdmin)return true;if(profile)return ['teacher','staff'].includes(profile.role);return ['teacher','staff'].includes($('role')?.value||demoAudience);}
