 page('Cadastro de avaliação',`${field('exam-title','Título da avaliação',data.title)}${select('exam-mode','Formato',[['assessment','Avaliação individual'],['programming','Avaliação de programação'],['live','Quiz ao vivo']],data.mode||'assessment')}${select('exam-subject','Disciplina',(owner()?subjectsOf(course):visibleSubjects()).map(subject=>[subject,subject]),data.subject)}${field('exam-date','Data de referência (opcional)',data.date,'date')}${availabilityFields(data)}${select('exam-grading','Forma de avaliação',[['concept','Conceitos (níveis configuráveis na rubrica)'],['grade','Nota numérica']],data.grading)}${field('exam-scale','Nota máxima da avaliação',data.scale,'number')}${programmingFields(data.programming)}<p class="muted">As questões têm pesos individuais. O resultado é convertido para nota ou conceito ao corrigir.</p><h2>Questões</h2><div id="question-list"></div>${button('add-question','Adicionar questão','outline')}${button('exam-bank','Adicionar questão do banco','outline')}<div id="exam-bank-list"></div><div class="actions">${button('exam-save','Salvar avaliação')}${button('exam-cancel','Cancelar','outline')}</div>`,exams);
 wireAvailability();const editor=mountQuestionEditor($('question-list'),data.questions,{onError:error});if(!data.questions.length)editor.append(data.mode==='programming'?{id:id(),type:'open',points:1,prompt:'',responseFormat:'code'}:undefined);wireProgrammingFields();
 on('add-question',()=>editor.append(val('exam-mode')==='programming'?{id:id(),type:'open',points:1,prompt:'',responseFormat:'code'}:undefined));on('exam-bank',async()=>{const bank=await D.list('sparkBank',[['ownerUid','==',user.uid]]);$('exam-bank-list').innerHTML=bank.length?bank.map((entry,i)=>`<div class="card"><p>${esc(entry.question.prompt)}</p>${button('use-bank-'+i,'Usar questão','outline')}</div>`).join(''):'<p>Seu banco de questões está vazio.</p>';bank.forEach((entry,i)=>on('use-bank-'+i,()=>{editor.append({...structuredClone(entry.question),id:id()});}));});on('exam-cancel',exams);
