 if(existing?.rubric&&existing.rubric.mode!==examData.grading)throw Error('A forma de avaliação precisa coincidir com a rubrica existente. Crie outra avaliação para trocar o formato.');if(examData.mode==='programming'){examData.programming=readProgrammingFields();if(examData.questions.some(q=>q.type!=='open'))throw Error('Avaliação de programação aceita somente questões abertas. Selecione Resposta aberta nas questões.');examData.questions.forEach(q=>q.responseFormat='code');}if(!examData.title)throw Error('Informe o título da avaliação.');if(!examData.questions.length)throw Error('Adicione pelo menos uma questão.');
