function question(q){let prompt=esc(q.prompt);if(q.type==='blanks')prompt=prompt.replace(/\{\{(\d+)\}\}/g,(_,n)=>`<input aria-label="Lacuna ${n}" style="display:inline-block;width:180px" maxlength="100">`);return `<section class="card" id="q-${q.id}"><h2>${prompt}</h2>${q.code?`<pre style="background:#101418;color:#e8edf2;padding:20px;overflow:auto"><code>${esc(q.code)}</code></pre>`:''}${['choice','multiple'].includes(q.type)?q.options.map((s,i)=>`<label class="option"><input type="${q.type==='choice'?'radio':'checkbox'}" name="${q.id}" value="${i}">${esc(s)}</label>`).join(''):q.type==='open'?`<textarea rows="5" maxlength="20000" aria-label="Resposta" style="${q.responseFormat==='code'?'background:#101418;color:#e8edf2;font-family:monospace':''}"></textarea>`:''}</section>`;}
async function takeExam(e){if(e.mode==='live')return live(e);examId=e.id;const prev=await D.read(ep()+'/attempts/'+user.uid);if(prev){const grade=await D.read(ep()+'/grades/'+user.uid);page('Sua entrega',`<p>Enviada em ${date(prev.submittedAt)}.</p>${e.mode==='programming'?e.questions.map(q=>'<h2>'+esc(q.prompt)+'</h2><pre class="programming-submitted">'+esc(programmingText(prev.answers[q.id]))+'</pre>').join(''):''}${grade?`<h2>${e.grading==='concept'?esc(grade.concept):grade.grade+' / '+e.scale}</h2>${Object.entries(grade.feedback).map(([k,v])=>`<p><strong>${esc(k)}</strong>: ${v.points} pontos · ${esc(v.feedback)}</p>${v.rubric?rubricFeedbackSummary(v.rubric):''}`).join('')}`:'<p>Aguardando correção do professor.</p>'}`);return;}const state=await assertExamWindow(e,false);if(!state){page('Avaliação indisponível',`<p>${esc(availabilityStatus(e))}. Atualize a lista para conferir a liberação.</p>`,exams);return;}page(e.title,`<p>${esc(e.subject)} · Respostas enviadas uma única vez.</p><div class="notice">Saídas de foco e ações de copiar/colar podem ser registradas para análise do professor. Não comprovam fraude. O navegador não bloqueia nem detecta capturas de tela de forma confiável.</div>${e.rubric?rubricDescription(e.rubric):''}${e.questions.map(question).join('')}${button('submit','Enviar respostas')}`,exams);assessment=e;if(e.mode==='programming'){const generation=programGeneration;for(const q of e.questions){const controller=await mountProgramming($('q-'+q.id),validateProgramming(e.programming),{onDirty:()=>app.dispatchEvent(new window.Event('input',{bubbles:true}))});if(generation!==programGeneration){controller.destroy();return;}programEditors.set(q.id,controller);}}on('submit',async()=>{const answers={};for(const q of e.questions)answers[q.id]=e.mode==='programming'?programEditors.get(q.id).read():publicAnswers(q,$('q-'+q.id));if(e.mode==='programming'&&new TextEncoder().encode(JSON.stringify(answers)).byteLength>650000)throw Error('O conjunto de respostas está muito grande. Reduza para até 650 KB antes de enviar.');if(!confirm('Enviar definitivamente? Depois não será possível alterar.'))return;await assertExamWindow(e,true);await D.put(ep()+'/attempts/'+user.uid,{uid:user.uid,name:profile.name,answers,submittedAt:now()});assessment=null;takeExam(e);});}
let lastEvent=0;async function logEvent(type){if(!assessment||!user||Date.now()-lastEvent<1500)return;lastEvent=Date.now();try{await D.put(ep()+'/events/'+id(),{uid:user.uid,type,createdAt:now()});}catch(e){console.warn('Evento não registrado',e.code);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)logEvent('hidden');});window.addEventListener('blur',()=>logEvent('blur'));for(const t of ['copy','paste','contextmenu'])document.addEventListener(t,()=>logEvent(t));
async function reviewList(e){const attempts=await D.list(ep()+'/attempts'),grades=await D.list(ep()+'/grades');page('Entregas · '+e.title,table(['Aluno','Entregue em','Resultado','Ação'],attempts.map(a=>{const g=grades.find(g=>g.id===a.uid);return [esc(a.name),date(a.submittedAt),g?e.grading==='concept'?g.concept:g.grade:'A corrigir',button('review-'+a.uid,'Corrigir')];})));for(const a of attempts)on('review-'+a.uid,()=>review(e,a));}
async function review(e,a){const key=await D.read(ep()+'/private/key'),events=await D.list(ep()+'/events',[['uid','==',a.uid]]),previous=await D.read(ep()+'/grades/'+a.uid);page('Correção · '+a.name,`${e.questions.map(q=>`<section class="card"><h2>${esc(q.prompt)}</h2><pre style="white-space:pre-wrap">${esc(e.mode==='programming'?programmingText(a.answers[q.id]):JSON.stringify(a.answers[q.id],null,2))}</pre>${q.type==='open'?(e.rubric?rubricControls('exam-rubric-'+q.id,e.rubric,previous?.feedback?.[q.id]?.rubric?.criteria.map(c=>c.value)):field('points-'+q.id,`Pontos (0 a ${q.points})`,previous?.feedback?.[q.id]?.points||0,'number')):'<p>Correção automática ao salvar no painel do professor.</p>'}${field('feedback-'+q.id,'Feedback',previous?.feedback?.[q.id]?.feedback||'')}</section>`).join('')}${select('grade-period','Período para lançar no conselho',course.periods.map(p=>[p,p]),course.periods[0])}${e.grading==='concept'&&e.rubric?select('exam-final-concept','Conceito final',[['','Selecione'],...e.rubric.levelNames.map(n=>[n,n])],previous?.concept||''):''}${field('deduction','Desconto em pontos brutos (após análise do professor)',0,'number')}${field('reason','Justificativa do desconto')}${button('grade-save','Calcular e publicar resultado')}<h2>Registros de navegação</h2><p>Eventos são indícios técnicos, não prova de fraude. Não há detecção garantida de prints.</p>${table(['Evento','Momento'],events.map(v=>[esc(v.type),date(v.createdAt)]))}`);on('grade-save',async()=>{const manual={};for(const q of e.questions)manual[q.id]={points:Number($('points-'+q.id)?.value||0),feedback:val('feedback-'+q.id)};const rubricScores={};if(e.rubric)for(const q of e.questions.filter(q=>q.type==='open')){const result=rubricResult(e.rubric,e.rubric.criteria.map((c,i)=>val('exam-rubric-'+q.id+'-'+i)));manual[q.id].points=result.percent/100*q.points;rubricScores[q.id]=result;}const g=gradeAttempt(e,key.keys,a.answers,manual);for(const [qid,result]of Object.entries(rubricScores))g.feedback[qid].rubric=result;const discount=Number(val('deduction'));if(!Number.isFinite(discount)||discount<0||discount>g.total||(discount>0&&!val('reason')))throw Error('Desconto inválido ou sem justificativa.');g.earned=Math.max(0,g.earned-discount);g.percent=g.earned/g.total*100;g.grade=Math.round(g.percent/100*e.scale*100)/100;g.concept=g.percent>=99.999?'A':g.percent>=70?'B':g.percent>=40?'C':'D';if(e.grading==='concept'&&e.rubric){g.concept=val('exam-final-concept');if(!e.rubric.levelNames.includes(g.concept))throw Error('Selecione o conceito final.');}await D.put(ep()+'/grades/'+a.uid,{...g,subject:e.subject,grading:e.grading,scale:e.scale,discount,reason:val('reason'),authorUid:user.uid,authorName:profile.name,updatedAt:now()});await D.put(cp()+'/records/'+id(),{kind:'result',studentUid:a.uid,studentName:a.name,subject:e.subject,period:val('grade-period'),grading:e.grading,concept:g.concept,grade:g.grade,scale:e.scale,text:'Avaliação: '+e.title,authorUid:user.uid,authorName:profile.name,createdAt:now()}).catch(err=>{console.warn('Lançamento no acompanhamento indisponível',err.code);});reviewList(e);});}
async function live(e){if(e.mode==='assessment')throw Error('Esta atividade é uma avaliação individual.');examId=e.id;const state=await D.read(ep()+'/live/state');if(!subjectManager()){page('Quiz ao vivo · '+e.title,'<div id="live-student">Aguardando professor…</div>');const render=s=>{if(!s||!s.open){$('live-student').innerHTML='<p>Aguarde a abertura da pergunta.</p>';return;}const q=e.questions.find(q=>q.id===s.questionId);if(!q)return;const sent=localStorage.getItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`);$('live-student').innerHTML=sent?'<p>Resposta enviada. Aguarde a próxima pergunta.</p>':question(q)+button('live-send','Enviar');on('live-send',async()=>{const answer=publicAnswers(q,$('q-'+q.id));await assertExamWindow(e,true);await D.put(ep()+'/liveAnswers/'+user.uid+'_'+q.id,{uid:user.uid,name:profile.name,questionId:q.id,answer,createdAt:now()});localStorage.setItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`,'1');render(s);});};unsubs.push(D.watch(ep()+'/live/state',render,error));return;}
page('Quiz ao vivo · '+e.title,`${select('live-question','Pergunta',e.questions.filter(q=>q.type!=='blanks').map(q=>[q.id,q.prompt]),state?.questionId)}${select('chart','Gráfico',[['bars','Barras'],['pie','Pizza'],['dots','Bolinhas'],['wordcloud','Nuvem de palavras']],'bars')}${select('values','Valores',[['count','Numérico'],['percent','Porcentagem']],'count')}<div class="actions">${button('live-open','Abrir pergunta')}${button('live-close','Encerrar pergunta','outline')}${button('live-end','Encerrar quiz','outline')}</div><p id="live-state"></p><div id="live-chart" class="card"></div>`);let responses=[];const render=()=>{const q=e.questions.find(q=>q.id===val('live-question')),rows=responses.filter(r=>r.questionId===q.id);$('live-chart').innerHTML=chart(q,rows,val('chart'),val('values'));};on('live-open',async()=>{const current=await D.read(ep()),time=releaseMillis(await D.serverNow());if((releaseMillis(current.startAt)||0)>time)throw Error('A liberação está agendada. Use Liberar agora para antecipar.');if((releaseMillis(current.endAt)||Infinity)<=time)throw Error('O prazo terminou. Ajuste o encerramento ou use Liberar agora.');await D.patch(ep(),{open:true,published:true,releaseMode:current.releaseMode==='scheduled'?'scheduled':'instant'});await D.put(ep()+'/live/state',{open:true,questionId:val('live-question')});$('live-state').textContent='Recebendo respostas. Cada estudante pode responder uma vez por pergunta.';});on('live-end',async()=>{await closeExam(e);await exams();});on('live-close',async()=>{await D.put(ep()+'/live/state',{open:false,questionId:val('live-question')});$('live-state').textContent='Respostas encerradas.';});for(const k of ['live-question','chart','values'])$(k).onchange=render;unsubs.push(D.watchList(ep()+'/liveAnswers',[],r=>{responses=r;render();},error));}
function chart(q,rows,type,values){const counts=new Map();if(q.options)q.options.forEach((v,i)=>counts.set(String(i),0));for(const r of rows){if(q.type==='multiple'&&Array.isArray(r.answer))for(const n of new Set(r.answer))if(counts.has(String(n)))counts.set(String(n),counts.get(String(n))+1);else{}else if(q.type==='choice'){if(counts.has(String(r.answer)))counts.set(String(r.answer),counts.get(String(r.answer))+1);}else if(typeof r.answer==='string'){const words=type==='wordcloud'?[...new Set(r.answer.toLocaleLowerCase('pt-BR').match(/[\p{L}\p{N}]+/gu)||[])]:[r.answer];for(const w of words)counts.set(w,(counts.get(w)||0)+1);}}const total=[...counts.values()].reduce((a,b)=>a+b,0),max=Math.max(1,...counts.values()),colors=['#176f60','#c76740','#4479af','#9064b1','#b29430','#3b8892'];const entries=[...counts].slice(0,100);const label=n=>values==='percent'?`${(n/Math.max(1,type==='pie'?total:rows.length)*100).toFixed(1)}%`:n;let visual='';if(type==='wordcloud')visual=entries.map(([k,n],i)=>`<span style="display:inline-block;margin:10px;color:${colors[i%6]};font-size:${16+32*n/max}px">${esc(q.options?q.options[Number(k)]:k)} (${label(n)})</span>`).join('');else if(type==='pie'){let angle=0;const stops=entries.filter(([,n])=>n>0).map(([,n],i)=>{const start=angle;angle+=n/Math.max(1,total)*360;return `${colors[i%6]} ${start}deg ${angle}deg`;});visual=`<div role="img" aria-label="Gráfico de pizza; dados na tabela abaixo" style="width:220px;height:220px;border-radius:50%;background:${stops.length?'conic-gradient('+stops.join(',')+')':'#ddd'}"></div>`;}else visual=entries.map(([k,n])=>`<p>${esc(q.options?q.options[Number(k)]:k)}: <strong>${label(n)}</strong></p>${type==='dots'?`<div aria-label="${n} respostas" style="color:#176f60;font-size:22px">${'● '.repeat(Math.min(n,60))}${n>60?' +'+(n-60):''}</div>`:`<div style="height:20px;background:#176f60;width:${n/max*100}%"></div>`}`).join('');return `<h2>${rows.length} respostas</h2><p>${q.type==='multiple'?'Múltiplas escolhas: barras/bolinhas usam respondentes; pizza usa marcações.':''}</p>${visual}${table(['Resposta','Contagem','Exibição'],entries.map(([k,n])=>[esc(q.options?q.options[Number(k)]:k),n,label(n)]))}`;}
async function tracking(){const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),records=await D.list(cp()+'/records',selectedSubject?[['subject','==',selectedSubject]]:[]),settings=await D.list(cp()+'/trackingSettings');page(selectedSubject?'Acompanhamento · '+selectedSubject:'Acompanhamento geral',`<p>Mensagens conforme as regras do curso e da disciplina. Resultados anteriores permanecem visíveis.</p>${(owner()||subjectManager())&&!course.closed?button('tracking-config','Configurar mensagens e cores','outline'):''}${table(['Aluno','Situação','Ação'],students.map(s=>{const results=latestResults(records.filter(r=>r.studentUid===s.uid&&r.kind==='result'));return [esc(s.name),trackingSituation(results,settings),button('student-'+s.uid,'Abrir histórico')];}))}`);on('tracking-config',trackingSettings);for(const s of students)on('student-'+s.uid,()=>dossier(s));}
function latestResults(rows){const map=new Map();for(const r of rows.sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0)))map.set(r.subject+'|'+r.period,r);return [...map.values()];}
async function dossier(s){const records=await D.list(cp()+'/records',[['studentUid','==',s.uid],...(selectedSubject?[['subject','==',selectedSubject]]:[])]);page('Histórico · '+s.name,`${table(['Data','Tipo / disciplina / período','Autor','Resultado / observação','Documento'],records.sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)).map(r=>[date(r.createdAt),esc([r.kind,r.subject,r.period].filter(Boolean).join(' / ')),esc(r.authorName),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale)+' · '+r.text:r.text),r.kind==='written'?button('print-'+r.id,'Imprimir'):link(r.documentLink)]))}<h2>Novo lançamento</h2>${select('record-kind','Tipo',[['observation','Observação'],['result','Nota/conceito para conselho'],['verbal','Advertência verbal'],['written','Advertência escrita']],'observation')}${select('record-subject','Disciplina',(selectedSubject?[selectedSubject]:subjectsOf(course)).map(s=>[s,s]),selectedSubject||subjectsOf(course)[0])}${select('record-period','Período',course.periods.map(s=>[s,s]),course.periods[0])}<div id="record-evaluation-fields">${select('record-grading','Avaliação',[['concept','Conceito'],['grade','Nota']],'concept')}<div id="record-concept-fields">${field('record-concept','Conceito (conforme os níveis cadastrados)','A')}</div><div id="record-numeric-fields">${field('record-grade','Nota',0,'number')}${field('record-scale','Nota máxima',100,'number')}</div></div>${area('record-text','Observação / motivo da advertência')}${field('record-document','Documento adicional: link HTTPS')}${button('record-save','Registrar')}`);const updateRecordFields=()=>{const result=val('record-kind')==='result',numeric=result&&val('record-grading')==='grade';for(const [group,show] of [['record-evaluation-fields',result],['record-concept-fields',result&&!numeric],['record-numeric-fields',numeric]]){$(group).hidden=!show;for(const control of $(group).querySelectorAll('input,select'))control.disabled=!show;}};$('record-kind').onchange=updateRecordFields;$('record-grading').onchange=updateRecordFields;updateRecordFields();for(const r of records)on('print-'+r.id,()=>printWarning(s,r));on('record-save',async()=>{const kind=val('record-kind'),grade=Number(val('record-grade')),scale=Number(val('record-scale'));if(kind==='result'&&val('record-grading')==='concept'&&(!val('record-concept')||val('record-concept').length>60))throw Error('Informe um conceito de até 60 caracteres.');if(kind==='result'&&val('record-grading')==='grade'&&(!Number.isFinite(grade)||!Number.isFinite(scale)||scale<=0||grade<0||grade>scale))throw Error('Nota/escala inválida.');safeLink(val('record-document'));assertSubject(course,val('record-subject'));const r={kind,studentUid:s.uid,studentName:s.name,subject:val('record-subject'),period:val('record-period'),...(kind==='result'?(val('record-grading')==='concept'?{grading:'concept',concept:val('record-concept')}:{grading:'grade',grade,scale}):{}),text:val('record-text'),documentLink:val('record-document'),authorUid:user.uid,authorName:profile.name,createdAt:now(),header:course.warningHeader||'',footer:course.warningFooter||'',letterhead:course.letterhead||''};if(!r.text&&kind!=='result')throw Error('Descreva a observação/ocorrência.');await D.put(cp()+'/records/'+id(),r);dossier(s);});}
function printWarning(s,r){const w=window.open('','_blank');if(!w)throw Error('Permita a abertura da janela de impressão.');w.opener=null;w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Advertência</title><style>body{font:16px Arial;margin:22mm;line-height:1.6}footer{margin-top:50px}a{word-break:break-all}</style></head><body><header>${esc(r.header)}</header><h1>Advertência por escrito</h1><p>Curso: ${esc(course.title)} · Turma: ${esc(course.group)}</p><p>Estudante: ${esc(s.name)}</p><p>Data: ${esc(date(r.createdAt))}</p><p style="white-space:pre-wrap">${esc(r.text)}</p><p>Responsável pelo registro: ${esc(r.authorName)}</p><p>${link(r.letterhead,'Modelo/papel timbrado externo')}</p><p>____________________________<br>Ciência do estudante / responsável</p><footer>${esc(r.footer)}</footer></body></html>`);w.document.close();w.print();}
async function report(){const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),all=await D.list(cp()+'/records',selectedSubject?[['subject','==',selectedSubject]]:[]),rows=[],subjects=selectedSubject?[selectedSubject]:[...new Set([...subjectsOf(course),...all.filter(r=>r.kind==='result'&&r.subject).map(r=>r.subject)])];for(const s of students)for(const subject of subjects){const results=latestResults(all.filter(r=>r.studentUid===s.uid&&r.subject===subject&&r.kind==='result'));rows.push([esc(s.name),esc(subject),...course.periods.map(p=>{const r=results.find(r=>r.period===p);return r?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):'—';})]);}const html=`<h1>${esc(course.title)}${selectedSubject?' · '+esc(selectedSubject):''} · Conselho acumulativo</h1><p>Períodos apresentados lado a lado, sem somar conceitos. Autor e revisões ficam no histórico do aluno.</p>${table(['Estudante','Disciplina',...course.periods.map(esc)],rows)}`;page('Relatório de conselho',html+button('report-print','Imprimir / salvar PDF')+button('report-download','Baixar relatório HTML','outline'));on('report-print',()=>window.print());on('report-download',()=>download('conselho-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html'));return html;}
async function bankPanel(){const items=await D.list('sparkBank',[['ownerUid','==',user.uid]]);page('Banco de questões',`<p>Cadastre uma questão pelos campos abaixo. No cadastro da avaliação, você pode usar questões do seu banco.</p><div id="bank-question-editor"></div>${button('bank-save','Salvar questão')}<h2>Questões cadastradas</h2>${items.map(q=>`<details><summary>${esc(q.question.prompt)}</summary><p>${esc(q.question.type)} · Peso ${esc(q.question.points)}</p></details>`).join('')}`);const editor=mountQuestionEditor($('bank-question-editor'),[],{onError:error});editor.append();on('bank-save',async()=>{const questions=editor.read();if(questions.length!==1)throw Error('Preencha uma questão.');splitExam({...SAMPLE,questions});await D.put('sparkBank/'+id(),{ownerUid:user.uid,question:questions[0]});await bankPanel();});}

const childCollections=['instructors','roster','team','requests','admissionHistory','trackingSettings','students','notices','calendar','lessons','progress','records','exams','assignments','closures'];
async function collectCourse(cid){const prefix='sparkCourses/'+cid,c=await D.read(prefix),out=[{path:prefix,data:D.encode(stripId(c))}];for(const col of childCollections){const rows=await D.list(prefix+'/'+col);for(const row of rows){const path=prefix+'/'+col+'/'+row.id;out.push({path,data:D.encode(stripId(row))});if(col==='exams'||col==='assignments')for(const sub of (col==='assignments'?['submissions','grades']:['private','attempts','grades','events','live','liveAnswers']))for(const child of await D.list(path+'/'+sub))out.push({path:path+'/'+sub+'/'+child.id,data:D.encode(stripId(child))});}}return out;}
function stripId({id,...data}){return data;}
async function backupPanel(){page('Backup e restauração',`<p>Backup JSON desta edição Spark: perfis, planos, cursos, matrículas, conteúdos, avaliações, gabaritos, respostas, acompanhamento e demonstração. Não inclui contas do Authentication, documentos externos ou o cadastro de administradores.</p>${button('backup-export','Baixar backup completo')}<h2>Restaurar</h2><p>Restauração administrativa, em lotes. Sobrescreve caminhos presentes no JSON, preserva os demais e pode ficar parcial se houver falha. Guarde um backup atual antes de prosseguir.</p><input id="backup-file" type="file" accept="application/json">${field('restore-confirm','Digite RESTAURAR')}${button('backup-restore','Restaurar backup','danger')}<p id="backup-status"></p>`);on('backup-export',async()=>{const docs=[];for(const root of ['sparkProfiles','sparkRegistrationDecisions','sparkInstitutions','sparkPlans','sparkPlanPayments','sparkInvites','sparkLeads','sparkBank'])for(const row of await D.list(root))docs.push({path:root+'/'+row.id,data:D.encode(stripId(row))});for(const c of await D.list('sparkCourses'))docs.push(...await collectCourse(c.id));download('conexoes-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});$('backup-status').textContent='Download solicitado. Confira se o arquivo foi salvo no computador.';});on('backup-restore',async()=>{if(val('restore-confirm')!=='RESTAURAR')throw Error('Confirme digitando RESTAURAR.');const f=$('backup-file').files[0];if(!f||f.size>20000000)throw Error('Selecione um JSON de até 20 MB.');const b=validateBackup(JSON.parse(await f.text()));if(!confirm(`Restaurar ${b.docs.length} documentos?`))return;await D.batch(b.docs.map(x=>({path:x.path,data:D.decode(x.data)})));$('backup-status').textContent='Restauração concluída.';});}
async function closure(){if(course.closed){return closedCourse();}
page('Fechamento do curso / ano',`<p>O relatório apresenta todos os períodos do curso e suas disciplinas. Feche cada curso do ano desejado separadamente.</p><p>Antes de encerrar, visualize os relatórios e confira o download do backup JSON.</p>${button('close-report','1. Visualizar e baixar relatório')}${button('close-backup','2. Baixar backup do curso')}<div id="close-output"></div><label><input id="close-read" type="checkbox"> Visualizei o relatório de fechamento.</label><label><input id="close-downloaded" type="checkbox"> Confirmei que o backup JSON foi salvo e pode ser recuperado.</label>${button('close-final','3. Encerrar e bloquear lançamentos','danger')}`);let viewed=false,downloaded=false,downloadHash='';on('close-report',async()=>{const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),records=await D.list(cp()+'/records');const html=`<h1>Fechamento · ${esc(course.title)}</h1><p>${esc(course.start)} a ${esc(course.end)}</p>${table(['Aluno','Disciplina','Período','Resultado','Autor','Observação'],records.map(r=>[esc(students.find(s=>s.uid===r.studentUid)?.name||r.studentName),esc(r.subject),esc(r.period),r.kind==='result'?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):esc(r.kind),esc(r.authorName),esc(r.text)]))}`;$('close-output').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');viewed=true;});on('close-backup',async()=>{const docs=await collectCourse(courseId);download('curso-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});downloadHash=await fingerprint(docs);downloaded=true;});on('close-final',async()=>{if(!viewed||!downloaded||!$('close-read').checked||!$('close-downloaded').checked)throw Error('Conclua o relatório, o download e as confirmações.');if(await fingerprint(await collectCourse(courseId))!==downloadHash)throw Error('Dados mudaram após o backup. Gere novamente o relatório e o backup antes de encerrar.');await D.put(cp()+'/closures/'+id(),{authorUid:user.uid,authorName:profile.name,createdAt:now(),reportConfirmed:true,backupConfirmed:true,snapshotHash:downloadHash});await D.patch(cp(),{closed:true});openCourse(courseId);});}
async function renewPlan(){const plans=await D.list('sparkPlans'),available=plans.filter(p=>p.active!==false);page('Meu plano e renovação',`<p>Plano atual: ${esc(profile.planId||'free')} · Validade: ${esc(date(profile.planExpiresAt))}</p><p>Planos gratuitos não exigem comprovante. Para planos pagos, o pagamento é externo e a administração valida o link e a validade.</p>${select('renew-plan','Plano',available.map(p=>[p.id,p.title||p.id]),profile.planId||'free')}${select('renew-cycle','Ciclo',[['monthly','Mensal'],['quarterly','Trimestral'],['semiannual','Semestral'],['yearly','Anual']],'monthly')}${field('renew-proof','Link do comprovante')}${button('renew-send','Solicitar validação')}`);const refresh=()=>{const p=available.find(p=>p.id===val('renew-plan')),free=p?.price===0;$('renew-proof').required=!free;$('renew-proof').previousElementSibling.textContent=free?'Link do comprovante (opcional para plano gratuito)':'Link do comprovante (obrigatório para plano pago)';$('renew-cycle').disabled=free;};$('renew-plan').onchange=refresh;refresh();on('renew-send',async()=>{const p=available.find(p=>p.id===val('renew-plan'));if(!p||typeof p.price!=='number'||p.price<0)throw Error('Selecione um plano cadastrado e válido.');if(p.price>0&&!val('renew-proof'))throw Error('Informe o comprovante para o plano pago.');if(val('renew-proof'))safeLink(val('renew-proof'));await D.put('sparkPlanPayments/'+user.uid,{uid:user.uid,planId:p.id,cycle:val('renew-cycle'),receiptLink:val('renew-proof'),createdAt:now()});alert('Solicitação enviada para validação administrativa.');home();});}
async function fingerprint(docs){const ordered=v=>Array.isArray(v)?v.map(ordered):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])])):v;const text=JSON.stringify(ordered([...docs].sort((a,b)=>a.path.localeCompare(b.path))));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function closedCourse(){page('Curso encerrado',`<p>Curso bloqueado para novos lançamentos. As contas e outros cursos serão preservados.</p>${button('closed-report','Visualizar e baixar relatório')}${isAdmin?button('closed-backup','Baixar backup atualizado'):''}<div id="closed-report-out"></div>${isAdmin?`<label><input id="purge-report" type="checkbox"> Visualizei os relatórios de fechamento.</label><label><input id="purge-backup" type="checkbox"> Confirmei que o backup JSON foi salvo e poderá ser recuperado.</label>${field('purge-text','Digite EXCLUIR '+courseId)}${button('purge','Excluir dados deste curso','danger')}`:''}`);let seen=false,downloaded=false,hash='';on('closed-report',async()=>{const records=await D.list(cp()+'/records');const html=`<h1>${esc(course.title)} · Fechamento</h1>${table(['Aluno','Disciplina','Período','Resultado / registro','Autor'],records.map(r=>[esc(r.studentName),esc(r.subject),esc(r.period),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):r.text),esc(r.authorName)]))}`;$('closed-report-out').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');seen=true;});on('closed-backup',async()=>{const docs=await collectCourse(courseId);download('curso-encerrado-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});hash=await fingerprint(docs);downloaded=true;});on('purge',async()=>{if(!seen||!downloaded||!$('purge-report').checked||!$('purge-backup').checked||val('purge-text')!=='EXCLUIR '+courseId)throw Error('Visualize o relatório, baixe o backup e preencha todas as confirmações.');const docs=await collectCourse(courseId);if(await fingerprint(docs)!==hash)throw Error('Dados mudaram após o backup. Baixe novamente antes de excluir.');if(!confirm('A exclusão dos dados deste curso será definitiva no banco. Continuar?'))return;await D.batch(docs.reverse().map(d=>({path:d.path,delete:true})));await D.remove('sparkInvites/'+courseId);home();});}
function shareUrl(cid,eid='',quiz=false){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('curso',cid);if(eid)u.searchParams.set('avaliacao',eid);if(quiz)u.searchParams.set('quiz','1');return u.href;}
